//go:build darwin

package clip

import (
	"runtime"
	"sync"
	"time"
	"unsafe"

	pobjc "github.com/ebitengine/purego/objc"

	"remote-support/agent-win/internal/darwin/objc"
)

// macOS pano (mimari-p28f §2 `clip_darwin.go`, §5.4 S-P28f-12): NSPasteboard düz metin, mevcut clip.go kuralları.
//   - Okuma yalnız `public.utf8-plain-text` verisidir (dönüştürücü `stringForType:` yok); panoda Concealed, Transient ya da
//     AutoGenerated işareti varsa içerik okunmaz (ErrSensitive). Veri uzunluğu kopyalamadan önce denetlenir.
//   - Yazma Windows'taki "geçmiş/bulut dışı" sözleşmesinin karşılığıdır: `NSPasteboardContentsCurrentHostOnly` (Evrensel
//     Pano'ya gitmez) + `org.nspasteboard.TransientType` (pano geçmişi tutan uygulamalar kaydetmez). Metin ve işaret tek
//     NSPasteboardItem'da tek `writeObjects:` ile konur (arada işaretsiz an yok). Teknisyenin koyduğu metin geri okunursa
//     ErrSensitive (Windows ile aynı, §5.3 r2).
//   - İşlemler AppKit ana iş parçacığında değil, kendi kilitli iş parçacığında sırayla yürür (ana döngü olmadan da çalışır);
//     çağıran en çok Timeout bekler. Her işlem kendi autorelease havuzundadır (objc.Pool).

const (
	typeText      = "public.utf8-plain-text"
	typeConcealed = "org.nspasteboard.ConcealedType"
	typeTransient = "org.nspasteboard.TransientType"
	typeAutoGen   = "org.nspasteboard.AutoGeneratedType"
	// NSPasteboardContentsCurrentHostOnly (macOS 10.12+).
	contentsCurrentHostOnly = 1
)

var (
	selGeneral    = objc.Sel("generalPasteboard")
	selUnique     = objc.Sel("pasteboardWithUniqueName")
	selRetain     = objc.Sel("retain")
	selTypes      = objc.Sel("types")
	selContains   = objc.Sel("containsObject:")
	selDataFor    = objc.Sel("dataForType:")
	selLength     = objc.Sel("length")
	selGetBytes   = objc.Sel("getBytes:length:")
	selPrepare    = objc.Sel("prepareForNewContentsWithOptions:")
	selWrite      = objc.Sel("writeObjects:")
	selClear      = objc.Sel("clearContents")
	selSetString  = objc.Sel("setString:forType:")
	selSetData    = objc.Sel("setData:forType:")
	selData       = objc.Sel("data")
	selArrayWith  = objc.Sel("arrayWithObject:")
	selReleaseAll = objc.Sel("releaseGlobally")
)

type macClip struct {
	pb      objc.ID // +1 tutulur
	unique  bool    // test panosu: Close'da releaseGlobally
	reqs    chan func()
	stop    sync.Once
	quit    chan struct{}
	stopped chan struct{}
}

// New genel panoyu (generalPasteboard) kullanan pano iş parçacığını başlatır. Çerçeve ya da sınıf çözülemezse hata
// (FFI kuralı 5): pano özelliği bildirilmez.
func New() (Clipboard, error) { return start(false) }

// start iş parçacığını kurar; unique yalnız testte (geliştiricinin panosuna dokunulmaz).
func start(unique bool) (*macClip, error) {
	c := &macClip{unique: unique, reqs: make(chan func(), 1), quit: make(chan struct{}), stopped: make(chan struct{})}
	ready := make(chan error, 1)
	go c.loop(ready)
	if err := <-ready; err != nil {
		return nil, err
	}
	return c, nil
}

// classes gereken sınıflar ve selector'ler çözülüyor mu (fail-closed).
func classes() (pb, item objc.Class, err error) {
	for _, fw := range []string{"Foundation", "AppKit"} {
		if _, err := objc.Framework(fw); err != nil {
			return 0, 0, ErrFailed
		}
	}
	if pb, err = objc.GetClass("NSPasteboard"); err != nil {
		return 0, 0, ErrFailed
	}
	if item, err = objc.GetClass("NSPasteboardItem"); err != nil {
		return 0, 0, ErrFailed
	}
	return pb, item, nil
}

func (c *macClip) loop(ready chan<- error) {
	runtime.LockOSThread() // bırakılmaz: goroutine bitince iş parçacığı da biter
	defer close(c.stopped)
	var err error
	objc.Pool(func() {
		var cls objc.Class
		if cls, _, err = classes(); err != nil {
			return
		}
		sel := selGeneral
		if c.unique {
			sel = selUnique
		}
		c.pb = objc.ID(cls).Send(sel).Send(selRetain)
		if c.pb == 0 || !objc.Responds(c.pb, selPrepare) || !objc.Responds(c.pb, selWrite) {
			objc.Release(c.pb)
			c.pb, err = 0, ErrFailed
		}
	})
	ready <- err
	if err != nil {
		return
	}
	for {
		select {
		case f := <-c.reqs:
			objc.Pool(f)
		case <-c.quit:
			objc.Pool(func() {
				if c.unique {
					c.pb.Send(selReleaseAll)
				}
				objc.Release(c.pb)
			})
			return
		}
	}
}

// do işi pano iş parçacığına verir ve en çok Timeout bekler. İş parçacığı meşgulse (önceki iş takıldı) ve kuyruk
// doluysa hemen ErrFailed; geç kalan iş son tarihi geçtiyse panoya dokunmadan döner (Windows ile aynı).
func (c *macClip) do(op func() error) error {
	select {
	case <-c.stopped:
		return ErrFailed
	default:
	}
	deadline := time.Now().Add(Timeout)
	res := make(chan error, 1)
	select {
	case <-c.stopped:
		return ErrFailed
	case c.reqs <- func() {
		if time.Now().After(deadline) {
			res <- ErrFailed
			return
		}
		res <- op()
	}:
	default:
		return ErrFailed
	}
	t := time.NewTimer(Timeout)
	defer t.Stop()
	select {
	case err := <-res:
		return err
	case <-t.C:
		return ErrFailed
	}
}

func (c *macClip) Close() {
	c.stop.Do(func() {
		close(c.quit)
		<-c.stopped
	})
}

func (c *macClip) ReadText() (string, error) {
	var s string
	err := c.do(func() (err error) {
		s, err = c.read()
		return err
	})
	return s, err
}

// read gizlilik işaretleri → `public.utf8-plain-text` verisi → uzunluk sınırı (kopyalamadan) → kopya → doğrulama.
func (c *macClip) read() (string, error) {
	types := c.pb.Send(selTypes)
	if types == 0 {
		return "", ErrEmpty
	}
	for _, mark := range []string{typeConcealed, typeTransient, typeAutoGen} {
		ns, err := objc.NSString(mark)
		if err != nil {
			return "", ErrFailed
		}
		if pobjc.Send[bool](types, selContains, ns) {
			return "", ErrSensitive
		}
	}
	nsText, err := objc.NSString(typeText)
	if err != nil {
		return "", ErrFailed
	}
	data := c.pb.Send(selDataFor, nsText)
	if data == 0 {
		return "", ErrEmpty
	}
	n := pobjc.Send[uint](data, selLength)
	switch {
	case n == 0:
		return "", ErrEmpty
	case n > maxGlobalBytes: // NUL'lar kırpılmadan önce kaba sınır; kesin sınır decodeUTF8'de
		return "", ErrTooLarge
	}
	buf := make([]byte, n)
	data.Send(selGetBytes, unsafe.Pointer(&buf[0]), n)
	runtime.KeepAlive(buf)
	s, err := decodeUTF8(buf)
	clear(buf)
	return s, err
}

func (c *macClip) WriteText(s string) error {
	if err := validateText(s); err != nil {
		return err
	}
	return c.do(func() error { return c.write(s) })
}

// write tek NSPasteboardItem (metin + TransientType) → CurrentHostOnly ile hazırlanan panoya tek writeObjects:. Herhangi
// bir adım başarısızsa pano boşaltılır (metin işaretsiz bırakılmaz).
func (c *macClip) write(s string) error {
	_, itemCls, err := classes()
	if err != nil {
		return err
	}
	dataCls, err := objc.GetClass("NSData")
	if err != nil {
		return ErrFailed
	}
	arrCls, err := objc.GetClass("NSArray")
	if err != nil {
		return ErrFailed
	}
	text, err := objc.NSString(s)
	if err != nil {
		return ErrInvalid
	}
	nsText, err1 := objc.NSString(typeText)
	nsTransient, err2 := objc.NSString(typeTransient)
	if err1 != nil || err2 != nil {
		return ErrFailed
	}
	item := objc.ID(itemCls).Send(objc.Sel("alloc")).Send(objc.Sel("init"))
	if item == 0 {
		return ErrFailed
	}
	defer objc.Release(item)
	empty := objc.ID(dataCls).Send(selData)
	if !pobjc.Send[bool](item, selSetString, text, nsText) || !pobjc.Send[bool](item, selSetData, empty, nsTransient) {
		return ErrFailed
	}
	objs := objc.ID(arrCls).Send(selArrayWith, item)
	if objs == 0 {
		return ErrFailed
	}
	c.pb.Send(selPrepare, uint(contentsCurrentHostOnly))
	if !pobjc.Send[bool](c.pb, selWrite, objs) {
		c.pb.Send(selClear)
		return ErrFailed
	}
	return nil
}
